          : await voiceLines(lines, { provider: deps.tts, voice: deps.voice, outDir: join(ctx.runDir, 'voice'), maxCalls: ctx.run.budget.maxTtsCalls });

      ctx.log(`${artifact.mode} cut, ${lines.length} lines, ${artifact.calls} TTS calls`);
